files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: #f0f0f0;
  padding: 16px;
}

.card {
  background: #2a2a40;
  border-radius: 24px;
  padding: 32px 24px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.6rem;
  font-weight: 600;
  text-align: center;
  color: #e0e0ff;
  letter-spacing: 0.5px;
}

.display {
  background: #151525;
  border-radius: 16px;
  padding: 16px;
  min-height: 80px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 2px solid #3a3a5a;
}

.entered {
  font-size: 2rem;
  letter-spacing: 8px;
  min-height: 2.4rem;
  color: #a0d0ff;
  font-weight: 600;
}

.status {
  font-size: 1.1rem;
  font-weight: 500;
  color: #c0c0e0;
  text-align: center;
  min-height: 1.4rem;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.keypad button {
  font-family: inherit;
  font-size: 1.4rem;
  font-weight: 600;
  padding: 16px 0;
  border: none;
  border-radius: 16px;
  background: #3a3a5a;
  color: #ffffff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  user-select: none;
}

.keypad button:hover {
  background: #50507a;
}

.keypad button:focus-visible {
  outline: 3px solid #a0d0ff;
  outline-offset: 2px;
}

.keypad button:active {
  background: #2a2a45;
  transform: scale(0.96);
}

.keypad button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: #3a3a5a;
  transform: none;
}

.keypad button[data-key="clear"] {
  background: #5a3a3a;
}

.keypad button[data-key="clear"]:hover {
  background: #7a4a4a;
}

.keypad button[data-key="enter"] {
  background: #3a5a3a;
}

.keypad button[data-key="enter"]:hover {
  background: #4a7a4a;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .keypad button {
    font-size: 1.2rem;
    padding: 12px 0;
  }
}

const CORRECT_CODE = '4271';
const MAX_ATTEMPTS = 3;
const LOCKOUT_MS = 10000;

const enteredEl = document.getElementById('entered');
const statusEl = document.getElementById('status');
const buttons = document.querySelectorAll('.keypad button');

let entered = '';
let wrongAttempts = 0;
let locked = false;
let lockTimer = null;

function updateDisplay() {
  enteredEl.textContent = entered || '\u00A0';
}

function setStatus(msg) {
  statusEl.textContent = msg;
}

function setLocked(state) {
  locked = state;
  buttons.forEach(btn => {
    btn.disabled = state;
  });
}

function startLockout() {
  setLocked(true);
  let remaining = LOCKOUT_MS / 1000;
  setStatus(`Locked for ${remaining}s`);
  lockTimer = setInterval(() => {
    remaining -= 1;
    if (remaining > 0) {
      setStatus(`Locked for ${remaining}s`);
    } else {
      clearInterval(lockTimer);
      lockTimer = null;
      setLocked(false);
      wrongAttempts = 0;
      entered = '';
      updateDisplay();
      setStatus('Enter code');
    }
  }, 1000);
}

function handleKey(key) {
  if (locked) return;

  if (key === 'clear') {
    entered = '';
    updateDisplay();
    setStatus('Enter code');
    return;
  }

  if (key === 'enter') {
    if (entered === CORRECT_CODE) {
      setStatus('Unlocked');
      entered = '';
      updateDisplay();
      wrongAttempts = 0;
    } else {
      entered = '';
      updateDisplay();
      wrongAttempts += 1;
      if (wrongAttempts >= MAX_ATTEMPTS) {
        startLockout();
      } else {
        setStatus('Wrong code');
      }
    }
    return;
  }

  if (entered.length < 4) {
    entered += key;
    updateDisplay();
    setStatus('');
  }
}

buttons.forEach(btn => {
  btn.addEventListener('click', () => {
    handleKey(btn.dataset.key);
  });
});

updateDisplay();
setStatus('Enter code');
